<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
type Task={id:number;title:string;status:string};type StateRow={id:number;task_id:number;title:string;elapsed_seconds:number;task_seconds:number};type TimerState={active:StateRow|null;paused:StateRow|null};type Session={id:number;started_at:string;ended_at:string|null;duration_seconds:number;end_reason:string|null};type Adjustment={id:number;time_session_id:number;previous_seconds:number;new_seconds:number;reason:string};
const props=defineProps<{selected:Task|null;csrf:string;disabled:boolean;version:number;timezone:string}>();const emit=defineEmits(['changed','working']);
const state=ref<TimerState>({active:null,paused:null}),busy=ref(false),error=ref(''),offline=ref(false),tick=ref(performance.now()),base=ref(performance.now()),sessions=ref<Session[]>([]),adjustments=ref<Adjustment[]>([]),total=ref(0),historyOpen=ref(false),editing=ref<Session|null>(null),seconds=ref(0),reason=ref('');
const pendingKeys=new Map<number,string>();let clock:ReturnType<typeof setInterval>|undefined,poller:ReturnType<typeof setInterval>|undefined;let syncing=false,generation=0;
const active=computed(()=>state.value.active),row=computed(()=>state.value.active||state.value.paused),delta=computed(()=>active.value?Math.max(0,Math.floor((tick.value-base.value)/1000)):0),elapsed=computed(()=>active.value?(active.value.elapsed_seconds+delta.value):0),taskTotal=computed(()=>row.value?(row.value.task_seconds+delta.value):0);
const format=(s:number)=>{s=Math.max(0,Math.floor(s));return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(n=>String(n).padStart(2,'0')).join(':')};
const date=(s:string)=>new Date(s).toLocaleString('ru-RU',{timeZone:props.timezone});
async function api(path:string,method='GET',data?:unknown){const r=await fetch(path,{method,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf},...(data===undefined?{}:{body:JSON.stringify(data)})});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Ошибка таймера');return d}
function apply(d:TimerState){state.value=d;base.value=performance.now();tick.value=base.value;offline.value=false}
async function getHistory(){const id=props.selected?.id;if(!id)return;const d=await api('/tasks/'+id+'/time');if(props.selected?.id===id){sessions.value=d.sessions;total.value=d.total_seconds;adjustments.value=d.adjustments}}
async function sync(){if(syncing||busy.value)return;syncing=true;const stamp=generation;try{const d=await api('/timer');if(stamp===generation&&!busy.value){apply(d);if(historyOpen.value)await getHistory()}}catch{if(stamp===generation&&!busy.value)offline.value=true}finally{syncing=false}}
async function run(fn:()=>Promise<void>){if(busy.value||props.disabled)return;generation++;busy.value=true;emit('working',true);error.value='';try{await fn();await getHistory();emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Не удалось сохранить действие таймера';offline.value=!navigator.onLine}finally{busy.value=false;emit('working',false)}}
function start(taskId:number){run(async()=>{let key=pendingKeys.get(taskId);if(!key){key=crypto.randomUUID();pendingKeys.set(taskId,key)}const d=await api('/tasks/'+taskId+'/timer','POST',{request_key:key});apply(d);pendingKeys.delete(taskId)})}
function stop(reason:'pause'|'stop'){if(!row.value)return;const id=row.value.id;run(async()=>apply(await api('/timer/'+id+'/stop','POST',{reason})))}
function openHistory(){historyOpen.value=true;error.value='';getHistory().catch(()=>{error.value='Не удалось загрузить историю времени'})}
function adjust(){if(!editing.value)return;const id=editing.value.id;run(async()=>{apply(await api('/timer/'+id,'PATCH',{seconds:seconds.value,reason:reason.value.trim()}));editing.value=null;reason.value=''})}
function resumeVisibility(){if(!document.hidden)sync()}
onMounted(()=>{sync();clock=setInterval(()=>tick.value=performance.now(),1000);poller=setInterval(()=>{if(!document.hidden)sync()},20000);window.addEventListener('focus',resumeVisibility);window.addEventListener('online',resumeVisibility);document.addEventListener('visibilitychange',resumeVisibility)});
onUnmounted(()=>{clearInterval(clock);clearInterval(poller);window.removeEventListener('focus',resumeVisibility);window.removeEventListener('online',resumeVisibility);document.removeEventListener('visibilitychange',resumeVisibility)});
watch(()=>props.version,()=>sync());watch(()=>props.selected?.id,()=>{sessions.value=[];total.value=0;editing.value=null;if(historyOpen.value)getHistory().catch(()=>{})});
</script>
<template><div class="timer-module"><section v-if="selected" class="time-controls"><div><b>Время задачи</b><small>{{selected.title}}</small><small v-if="disabled">Перед действием таймера сохраните изменения задачи.</small></div><button v-if="active?.task_id===selected.id" :disabled="busy||disabled" @click="stop('pause')">Ⅱ Приостановить</button><button v-else :disabled="busy||disabled||selected.status==='done'" class="primary" @click="start(selected.id)">{{state.paused?.task_id===selected.id?'▷ Продолжить':'▷ Начать работу'}}</button><button :disabled="busy" @click="openHistory">История времени</button></section><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="offline" class="timer-warning" role="status">Связь с таймером не подтверждена. Последний отсчёт показан приблизительно; действия требуют соединения с сервером.</p>
<div v-if="row" class="timer-dock"><div class="timer-task"><b>{{active?'◉ Работаем':'Ⅱ Пауза'}}</b><span>{{row.title}}</span></div><div class="timer-numbers"><strong>{{active?format(elapsed):format(taskTotal)}}</strong><small v-if="active">Всего по задаче: {{format(taskTotal)}}</small></div><button v-if="active" :disabled="busy||disabled" @click="stop('pause')" aria-label="Пауза">Ⅱ</button><button v-else :disabled="busy||disabled" @click="start(row.task_id)" aria-label="Продолжить">▷</button><button :disabled="busy||disabled" @click="stop('stop')" aria-label="Завершить отсчёт">■</button></div>
<div v-if="historyOpen&&selected" class="overlay timer-overlay" @click.self="!busy&&(historyOpen=false)"><section class="modal time-history" role="dialog" aria-modal="true" aria-label="История времени"><div class="detail-head"><h2>Время задачи</h2><button @click="historyOpen=false" :disabled="busy" aria-label="Закрыть историю">×</button></div><p>{{selected.title}}</p><h2>{{format(active?.task_id===selected.id?taskTotal:total)}}</h2><p class="muted extras-note">Последние 30 сессий. Итог включает всю историю. Пауза закрывает сессию; продолжение создаёт новую.</p><article v-for="s in sessions" :key="s.id" class="session-row"><div><b>{{date(s.started_at)}}</b><small>{{s.ended_at?'До '+date(s.ended_at):'Таймер работает'}}</small><span>{{s.ended_at?format(s.duration_seconds):format(elapsed)}}</span></div><button v-if="s.ended_at" :disabled="busy" @click="editing=s;seconds=s.duration_seconds;reason=''">Исправить</button></article><p v-if="!sessions.length" class="muted">Учёт времени ещё не начат.</p><form v-if="editing" class="time-adjustment" @submit.prevent="adjust"><h3>Корректировка сессии</h3><label>Длительность в секундах<input type="number" v-model.number="seconds" min="0" max="604800" step="1" required :disabled="busy"></label><label>Причина изменения<textarea v-model="reason" required minlength="3" maxlength="500" :disabled="busy"></textarea></label><p class="muted extras-note">Было {{format(editing.duration_seconds)}}. Изменение и причина сохранятся в истории.</p><button class="primary" :disabled="busy||disabled">Подтвердить корректировку</button><button type="button" @click="editing=null" :disabled="busy">Отмена</button></form><details v-if="adjustments.length"><summary>История корректировок</summary><p v-for="a in adjustments" :key="a.id" class="muted extras-note">Сессия #{{a.time_session_id}}: {{format(a.previous_seconds)}} → {{format(a.new_seconds)}} · {{a.reason}}</p></details><p v-if="error" class="error">{{error}}</p></section></div></div></template>
